const units = [];

function choice(prompt, options, answer, feedback, hint) {
  return { type: 'choice', prompt, options, answer, feedback, hint };
}

function order(prompt, options, answer, feedback, hint) {
  return { type: 'order', prompt, options, answer, feedback, hint };
}

function input(prompt, answer, feedback, hint) {
  return { type: 'text', prompt, answer, feedback, hint };
}

function multi(prompt, options, answer, feedback, hint) {
  return { type: 'multi', prompt, options, answer, feedback, hint };
}

function reflect(prompt, criteria, note) {
  return { type: 'reflect', prompt, criteria, hint: note, feedback: 'Dein eigener Abgleich mit den Kriterien gehört zu dieser Übung.' };
}

function add(category, records) {
  for (const [id, name, subcategory, description, materials, cost, minutes, digital, title, goal, intro, exercise, transfer, projectTask, criteria, pitfall] of records) {
    units.push({
      id, name, category, subcategory, description, intro,
      level: 'Einstieg', materials, cost, minutes, digital,
      skills: [goal], project: projectTask, pitfall,
      prerequisites: [],
      freeOption: digital ? 'Die Einstiegslektion lässt sich im Browser bearbeiten.' : 'Beginne mit der Browserübung und nutze für den Praxistransfer vorhandenes oder geliehenes Material.',
      lessons: [{ title, goal, intro, steps: [
        exercise, transfer, reflect(projectTask, criteria, pitfall),
      ] }],
    });
  }
}

