export const hobbies = units;
function expand(id, records) {
  const hobby = units.find(item => item.id === id);
  for (const [title, goal, intro, first, second, practice, criteria, hint] of records) {
    hobby.skills.push(goal);
    hobby.lessons.push({ title, goal, intro, steps: [first, second, reflect(practice, criteria, hint)] });
  }
}

